import sys

lines = sys.stdin.read().splitlines()
rows, cols = map(int, lines[0].split())
grid = [list(map(int, lines[1 + r].split())) for r in range(rows)]

def flood(sr, sc):
    stack = [(sr, sc)]
    grid[sr][sc] = 0
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                grid[nr][nc] = 0
                stack.append((nr, nc))

islands = 0
for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 1:
            islands += 1
            flood(r, c)
print(islands)
